// SwitchboardServer is the server API for Switchboard service.
// All implementations must embed UnimplementedSwitchboardServer
// for forward compatibility.
type SwitchboardServer interface {
	// --- Identity / capability ---
	GetDaemonInfo(context.Context, *GetDaemonInfoRequest) (*DaemonInfo, error)
	// Full sbx option surface so the client editor covers 100% of kit options (FR-014).
	GetOptionManifest(context.Context, *GetOptionManifestRequest) (*OptionManifest, error)
	// Self-update this daemon's binary to a target release and restart. Streams
	// progress; the connection drops when the daemon restarts on the new binary.
	UpdateDaemon(*UpdateDaemonRequest, grpc.ServerStreamingServer[UpdateProgress]) error
	// --- Sandbox lifecycle (FR-001, FR-012a-f) ---
	ListSandboxes(context.Context, *ListSandboxesRequest) (*ListSandboxesResponse, error)
	// Server-streams progress (copy %, sbx output) then a terminal Sandbox (FR-028).
	LaunchSandbox(*LaunchSandboxRequest, grpc.ServerStreamingServer[LaunchProgress]) error
	StopSandbox(context.Context, *SandboxIdRequest) (*Sandbox, error)
	RestartSandbox(*SandboxIdRequest, grpc.ServerStreamingServer[LaunchProgress]) error
	DestroySandbox(context.Context, *SandboxIdRequest) (*DestroyResponse, error)
	RenameSandbox(context.Context, *RenameSandboxRequest) (*Sandbox, error)
	// DESTRUCTIVE (feature 004, FR-030): deletes the retained workspace copy and
	// re-seeds it from the recorded sources, then brings the sandbox back up on the
	// SAME container so installed packages / agent history survive. Streams copy
	// progress + sbx logs then a terminal Sandbox, exactly like LaunchSandbox.
	// Clients MUST confirm with the user before calling this.
	RefreshSandbox(*SandboxIdRequest, grpc.ServerStreamingServer[LaunchProgress]) error
	// --- Agent kits (feature 004, FR-031..034) ---
	// Kits are authored and owned CLIENT-side (like configs); the daemon only
	// materializes a KitSpec's spec.yaml into a directory the host `sbx` can consume.
	// Validate a kit without attaching it (`sbx kit validate`), for editor feedback.
	ValidateKit(context.Context, *ValidateKitRequest) (*ValidateKitResponse, error)
	// Attach a kit to an ALREADY-RUNNING sandbox (`sbx kit add`). sbx restarts the
	// sandbox to apply it; VM state is preserved. Kits CANNOT be removed from a
	// running sandbox — destroy and recreate to start clean. Streams sbx logs then
	// a terminal Sandbox.
	AddSandboxKit(*AddSandboxKitRequest, grpc.ServerStreamingServer[LaunchProgress]) error
	// --- Source discovery for the launch wizard (FR-007) ---
	ListSourceCandidates(context.Context, *ListSourceCandidatesRequest) (*ListSourceCandidatesResponse, error)
	// Pre-launch disk/resource check; returns warnings the client may override (FR-012f).
	CheckResources(context.Context, *CheckResourcesRequest) (*ResourceReport, error)
	// --- Sandbox tag (FR-021..024, feature 003): mutable, non-unique purpose label. ---
	SetSandboxTag(context.Context, *SetSandboxTagRequest) (*Sandbox, error)
	// --- Workspace -> sandbox resolution for `sxb` auto-open (FR-017/018, feature 003). ---
	ResolveWorkspace(context.Context, *ResolveWorkspaceRequest) (*ResolveWorkspaceResponse, error)
	// --- Agent interaction (FR-022, FR-023) ---
	PromptAgent(context.Context, *PromptAgentRequest) (*PromptAgentResponse, error)
	// Bidirectional PTY stream for the persistent terminal session (feature 003):
	// the first AgentOutput frame is a Snapshot (current-screen + scrollback redraw),
	// then live `data` frames follow. The session survives client detach.
	AttachAgent(grpc.BidiStreamingServer[AgentInput, AgentOutput]) error
	// --- Live updates: sandbox state changes + agent notifications (FR-024-026b, SC-008) ---
	// On (re)subscribe the daemon replays undelivered NotificationEvents (FR-026b).
	Subscribe(*SubscribeRequest, grpc.ServerStreamingServer[Event]) error
	AckNotification(context.Context, *AckNotificationRequest) (*AckNotificationResponse, error)
	// --- VS Code open helper (FR-027): daemon returns the container name + in-container
	//
	//	workspace path; the CLIENT builds the vscode-remote URI and runs `code` locally. ---
	GetVSCodeTarget(context.Context, *SandboxIdRequest) (*VSCodeTarget, error)
	// --- Escape hatch (feature 005) ---
	// The AI INVOKES a command over the agent-hook HTTP server (POST /escape-hatch/run,
	// see specs/005-escape-hatch/contracts/escape-hatch-http.md), NOT gRPC. These RPCs
	// are the CLIENT surface: approve/deny a gated run, and review runs this session.
	//
	// Approve or deny a REQUIRES_APPROVAL run that is PENDING_APPROVAL (FR-039). The
	// daemon blocks the run on a 5-minute deny-by-default window; this is the client's
	// input to that gate. Idempotent on an already-resolved run.
	DecideEscapeHatchRun(context.Context, *DecideEscapeHatchRunRequest) (*DecideEscapeHatchRunResponse, error)
	// List escape-hatch runs for a sandbox in the current daemon session (FR-042).
	// Runs are in-memory only ("session" = daemon uptime); empty sandbox_id => all
	// sandboxes on this host.
	ListEscapeHatchRuns(context.Context, *ListEscapeHatchRunsRequest) (*ListEscapeHatchRunsResponse, error)
	// --- Port forwarding (feature 006) ---
	// Services are DECLARED on a kit and started only by the developer's explicit
	// selection (FR-045) — nothing here is reachable by the sandbox's agent.
	//
	// Every service the sandbox's attached kits declare, joined with its current
	// instance state. The set is exactly Sandbox.services — no more.
	ListSandboxServices(context.Context, *ListSandboxServicesRequest) (*ListSandboxServicesResponse, error)
	// Start one declared service by NAME, validated against the sandbox's persisted
	// service set (an unknown name starts nothing => NOT_FOUND). Returns as soon as
	// the instance exists (STARTING); readiness arrives via Event.service_instance.
	// Idempotent: a STARTING/RUNNING service returns its existing instance (FR-048).
	StartSandboxService(context.Context, *StartSandboxServiceRequest) (*StartSandboxServiceResponse, error)
	// Terminate the whole process tree — graceful signal, bounded grace period, then
	// force-kill — releasing the port only once the listen port is observed free
	// (FR-048). Idempotent on an already-stopped service.
	StopSandboxService(context.Context, *StopSandboxServiceRequest) (*StopSandboxServiceResponse, error)
	// Byte relay that puts a RUNNING service on a port on the DEVELOPER'S machine.
	// One stream per accepted TCP connection; see PortForwardFrame.
	ForwardPort(grpc.BidiStreamingServer[PortForwardFrame, PortForwardFrame]) error
	// --- Edit sandbox sources (feature 007, FR-053..FR-067) ---
	// Both RPCs edit the seeded folder set of an EXISTING sandbox IN PLACE — the
	// sandbox is never stopped, restarted, or recreated (FR-054), and its state
	// never changes (no CREATING/ERROR transitions; a failed add leaves the sandbox
	// exactly as it was, FR-058). Eligible states: RUNNING, STOPPED. While another
	// add/remove/refresh is in flight for the same sandbox, both return
	// FAILED_PRECONDITION naming the in-flight operation (FR-066). Completed edits
	// reach other clients through the existing Event.sandbox_changed arm (FR-067);
	// edits are developer-initiated and therefore raise no inbox notification.
	//
	// Seed additional folders into an existing sandbox's workspace, honoring the
	// sandbox's recorded seeding mode (duplicate => verbatim copy; clone => repo
	// clone, non-repos refused). Streams the SAME LaunchProgress shape as
	// LaunchSandbox/RefreshSandbox: `copy` for duplication progress (FR-055),
	// `log_line` for clone/sbx-free host output, `blocked` (instead of `done`) when
	// the resource gate trips without override (FR-057), then a terminal `done`
	// carrying the updated Sandbox (its `sources` now includes the additions).
	//
	// Refused BEFORE any byte is copied (FR-056) — INVALID_ARGUMENT /
	// ALREADY_EXISTS / FAILED_PRECONDITION naming the offending folder — when: a
	// path is missing or not a directory; a folder name collides with a recorded
	// source, an on-disk top-level workspace entry, or another selection in the
	// same request; the folder name is the reserved ".switchboard"; a clone-mode
	// add is not a git repository (re-verified daemon-side); or the sandbox state
	// is CREATING/DESTROYING/ERROR.
	//
	// Failure atomicity (FR-058): the copy stages inside the workspace's reserved
	// internal folder and is renamed into place only when complete, so a live agent
	// never observes a partially copied seeded folder, and any failure removes all
	// staged/renamed content from this operation, leaving record and workspace
	// untouched.
	AddSandboxSources(*AddSandboxSourcesRequest, grpc.ServerStreamingServer[LaunchProgress]) error
	// Delete seeded folders' copies from an existing sandbox's workspace and drop
	// them from the record. DESTRUCTIVE for the sandbox's copy (never the origin):
	// the CLIENT is responsible for the FR-060 confirmation before calling — the
	// daemon does not re-confirm (the RefreshSandbox precedent).
	//
	// Targets are EXACT recorded SourceRef.path values; an unknown path is
	// NOT_FOUND and nothing in the batch is deleted. Refused up front when the
	// batch would leave the sandbox with zero seeded folders (FR-061,
	// FAILED_PRECONDITION) or while a declared service instance is starting or
	// running with its working directory at or beneath a selected folder (FR-062,
	// FAILED_PRECONDITION naming the service and the remedy). A folder whose copy
	// is already missing on disk is dropped from the record and counts as success
	// (FR-063). On a mid-batch deletion failure the folders already deleted STAY
	// dropped from the record — the record follows the disk (research R3) — and the
	// error names the folder that failed.
	//
	// Returns the updated Sandbox (its `sources` reflect exactly what remains).
	RemoveSandboxSources(context.Context, *RemoveSandboxSourcesRequest) (*Sandbox, error)
	// --- MCP gateway (feature 008, FR-072..FR-100) ---
	// Each daemon owns ONE gateway manager scoped to its host: every RPC below acts
	// on this host's `sbx mcp` registrations only. Registrations are the host
	// runtime's truth (read via `sbx mcp ls` on every list); switchboard owns only
	// the per-daemon attach-by-default marks and default attach mode
	// (McpGatewaySettings). All of them answer FAILED_PRECONDITION carrying
	// DaemonInfo.mcp_gateway_reason when the gateway cannot be managed here
	// (CLI missing, below the runtime baseline, not signed in — FR-079); an older
	// daemon answers UNIMPLEMENTED (the `u` update fan-out is the remedy).
	//
	// Lists registered servers decorated with marks (stale marks are dropped on
	// read) plus the daemon's settings (FR-073).
	ListMcpServers(context.Context, *ListMcpServersRequest) (*ListMcpServersResponse, error)
	// Registers a server WITHOUT authorizing (always `--skip-auth`; authorization
	// is the separate AuthorizeMcpServer step, research R2) and optionally marks it
	// attach-by-default (FR-074/FR-080). A host-run `command` server requires
	// acknowledge_local_execution = true (FR-076). Host diagnostics travel verbatim
	// in the error (FR-078).
	AddMcpServer(context.Context, *AddMcpServerRequest) (*McpServer, error)
	// Removes a registration and clears its mark (FR-074); the runtime's notes
	// about leftover credential material are relayed in `notes`.
	RemoveMcpServer(context.Context, *RemoveMcpServerRequest) (*RemoveMcpServerResponse, error)
	// Runs the host's authorization flow for a registered server (FR-075): streams
	// the authorization URL as soon as the runtime prints it (open it where YOU are;
	// never auto-opened on the host), then progress, then a terminal frame. Bounded
	// at 10 minutes daemon-side; cancelling the stream cancels the wait. The
	// registration is never changed by any outcome.
	AuthorizeMcpServer(*AuthorizeMcpServerRequest, grpc.ServerStreamingServer[McpAuthProgress]) error
	// Sets or clears the attach-by-default mark (FR-080). NOT_FOUND when the name
	// is not registered on this host.
	SetMcpServerDefault(context.Context, *SetMcpServerDefaultRequest) (*McpServer, error)
	// Sets the daemon's default attach mode (FR-100). Never touches existing sandboxes.
	SetMcpAttachMode(context.Context, *SetMcpAttachModeRequest) (*McpGatewaySettings, error)
	mustEmbedUnimplementedSwitchboardServer()
}

